p='core/signed_types.av'
s=open(p).read()
old='''/// A seat's marks as one word.
fn seat_marks(s: SignedSeat) -> int {
    if s.mutable { 1 } else { 0 } + if s.settled { 2 } else { 0 } + if s.defaulted { 4 } else { 0 } +
        if s.rest { 8 } else { 0 } +
        if s.state { 16 } else { 0 } +
        if s.unshared { 32 } else { 0 }
}'''
new='''/// A seat's marks as one word: every field of the seat but its type, which its fold carries, and its
/// name, which a fn value's seats don't have and no type is told apart by. One destructure names
/// them all, so a mark the seat gains is refused here until it is folded or set aside.
fn seat_marks(s: SignedSeat) -> int {
    let SignedSeat { ty: _, mutable, settled, defaulted, name: _, rest, state, unshared } = s
    [mutable, settled, defaulted, rest, state, unshared].fold(0, (word, on) -> word * 2 + if on { 1 } else { 0 })
}'''
assert old in s; s=s.replace(old,new); open(p,'w').write(s)
EOF
echo ok

