/// `kinds` and `lits` are `terminals` as bits — a class by its slot (bit 62: an `END`
/// that a closing `}` answers), a literal by its slot in 62-bit words; `asked` holds the
/// terminals no bit can say, judged the long way.
export type BranchStart = {
    terminals: List<StartTerm>,
    nullable: bool,
    in_rule: string,
    kinds: int = 0,
    lits: List<int> = [],
    asked: List<StartTerm> = [],
}

/// One branch of an Alt: items that must appear in order, plus the
/// branch's build directive and recovery policy. No build means
/// pass-through of the single sub-result. `start` is computed at
