`req.body_as()` into a seat typed `Result<Idea, Response>`.
export trait Made {
    static fn made(n: int) -> Self
}

export type Seven = { n: int }

impl Made for Seven {
    static fn made(n: int) -> Seven { Seven { n: n } }
}

export type Box<P> = { held: P, n: int }

impl Box {
    /// The box's number as a `T`, or a refusal.
    fn as_made<T: Made>() -> Result<T, string> {
        if self.n < 0 { fail "negative" }
        T.made(self.n)
    }
}

/// Pinned by the annotation, through `?`, inside a generic fn.
export fn through_generic<P>(b: Box<P>) -> Result<int, string> {
    let s: Seven = b.as_made()?
    s.n
}

/// The same, outside one.
export fn through_plain(b: Box<string>) -> Result<int, string> {
    let s: Seven = b.as_made()?
    s.n
}

/// Pinned by a binding first, then `?`, inside a generic fn.
export fn bound_first<P>(b: Box<P>) -> Result<int, string> {
    let got: Result<Seven, string> = b.as_made()
    let s = got?
    s.n
}
