/// enum variant's payload — with the DEFAULT a field may declare,
/// the PROMISES it makes its callee (`mut`, `const`) and the MARKS
/// written before it. An ABSENT type IS a unit enum variant, so one
/// shape covers both and no arm has to ask which kind it is. Its
/// span lives off the value, in the store's span table, keyed by
/// `id` — never a field here to keep in sync across a rebuild.
/// `says` makes the seat an EVENT a component declares (`on input(text:
/// string)`): the seats its handler is told, none for an event that
/// says nothing — and absent on every seat that is not an event.
/// `type_default` is a type parameter's written default (`E = never`),
/// what the parameter is where nothing pins it.
@derive(Identity)
@derive(Taped)
    }
}

/// What a parameter seat WRITES, as a grammar rule labels it: the
/// marks are words (`mut`, `const`, `state`, and `isolated` as `unshared`)
/// present or absent, the rest are the seat's own parts; a positional
/// enum payload writes no name. A rule ending
/// `-> Record.ParamSyntax` fills this, and the seat's builder reads it.
@derive(Grammar)
export type ParamSyntax = { marks: List<Mark> = [], state_field: bool = false, constant: bool = false, mutable: bool = false, state: bool = false, unshared: bool = false, spread: bool = false, name: Scoped?, ty: TypeRef?, default: ExprId?, variadic: bool = false, tdefault: TypeRef? = null, bound: TypeRef? = null }
