/// THE WALK-END VOICE: a lambda no seat ever fed speaks once —
/// the driver brings each hungry lambda here with the seat that
/// starved it, if one did.
export fn unfed_lambda(mut cx: TypeCx, e: ExprId, seat: TypeId?) {
    let name = first_param_name(cx, e)
    if seat == null { return never_heard(cx, e, name) }
    let at = seat!
    if name == "it" && cx.view.types.arrow_parts(at) != null { return pronoun_unseated(cx, e, at) }
    if name == "it" { return pronoun_starved(cx, e, at) }
    if cx.view.types.arrow_parts(at) != null { return misfit_lambda(cx, e, at) }
    if cx.view.store.written_as_block(e) { return block_at_scalar(cx, e, at) }
    lambda_at_scalar(cx, e, at)
}

fn first_param_name(cx: TypeCx, e: ExprId) -> string {
    let parts? = cx.view.store.lambda_parts(e) else { return "the parameter" }
    parts.params.first()?.name?.of ?? "the parameter"
}

// ── The voices ──

fn not_offered(mut cx: TypeCx, e: ExprId, name: string, offered: List<string>) -> TypeId {
    cx.spoken(said_as("type.not_offered", cx.loc_of(e), offer_unnamed(name, offered)))
}

fn typed_offer(mut cx: TypeCx, e: ExprId, name: string) -> TypeId { cx.spoken(said_as("type.not_offered", cx.loc_of(e), offer_typed(name))) }

/// A lambda taking its seat's record by name asking for `name`, where it offers `offered`.
export fn offer_unnamed(name: string, offered: List<string>) -> Voice {
    Voice {
        message: "`${name}` is not offered here — this seat offers ${offered_list(offered)}",
        label: "`${name}` asked for here",
        help: "name what the seat offers, in any order and any subset",
    }
}

/// A lambda taking its seat's record by name writing its field `name` a type.
export fn offer_typed(name: string) -> Voice {
    Voice {
        message: "`${name}` is taken by name, so it wears the offered field's type",
        label: "annotated here",
        help: "drop the annotation",
    }
}

fn offered_list(names: List<string>) -> string {
    names.map("`${it}`").join(", ")
}

