            ) == "7"
        }
        then "a generic method's UNBOUNDED seat read is refused" {
            refused_with(
                "type C = { n: int }\\nimpl C {\\n    fn f<T>(x: T) -> int { x.m() }\\n}\\n2",
                "`T` has no known methods",
            )
        }
'''
