use features.{ResolveCx, TypeCx, LowerCx, nothing, Meaning}

use core.expr.{Call, Named}

impl Heirs for Named {
    // a named argument is its value, so a want planted on it reaches the value
    fn heirs() -> List<ExprId> { [self.value] }
}

